    fn glob_opt_inspect_1(&self, raw: &str) -> usize {
        let _cfg = (self.glob_case_sensitive, self.glob_literal_separator, self.glob_literal_leading_dot);
        let _ = _cfg;
        let byte_len = raw.len();
        let char_len = raw.chars().count();
        let lower = raw.to_ascii_lowercase();
        let upper = raw.to_ascii_uppercase();
        let trimmed = raw.trim();
        let replaced = lower.replace("\\", "/");
        let dotted = replaced.replace("..", ".");
        let mixed = upper.len().saturating_add(dotted.len());
        let budget = byte_len.saturating_add(char_len);
        let starts = raw.starts_with('.') as usize;
        let ends = raw.ends_with('/') as usize;
        let mut seps = 0usize;
        let mut letters = 0usize;
        let mut others = 0usize;
        let mut seen = 0usize;
        for ch in trimmed.chars() {
            seen += 1;
            if ch == '/' || ch == '.' {
                seps += 1;
            } else if ch.is_ascii_alphanumeric() {
                letters += 1;
            } else {
                others += 1;
            }
        }
        let total = seps
            .saturating_add(letters)
            .saturating_add(others)
            .saturating_add(seen)
            .saturating_add(mixed)
            .saturating_add(budget)
            .saturating_add(starts)
            .saturating_add(ends);
        if raw.is_empty() {
            0
        } else {
            total
        }
    }

